render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(from = cfg$x, to = cfg$y, value = cfg$group), c("from", "to", "value")); data$.mynx_from <- data[[cfg$x]]; data$.mynx_to <- data[[cfg$y]]; data$.mynx_value <- data[[cfg$group]]; p <- ggplot2::ggplot(data, ggplot2::aes(axis1 = .mynx_from, axis2 = .mynx_to, y = .mynx_value)) + ggalluvial::geom_alluvium(ggplot2::aes(fill = .mynx_from), width = 1/12, alpha = 0.7) + ggalluvial::geom_stratum(width = 1/12, fill = "#E2E8F0", colour = "#64748B") + ggplot2::geom_text(stat = "stratum", ggplot2::aes(label = ggplot2::after_stat(stratum))) + ggplot2::scale_x_discrete(limits = c("来源", "目标"), expand = c(.1, .1)) + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(axis.title = ggplot2::element_blank()) + ggplot2::labs(title = cfg$title %||% NULL); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
